-- Docente: Luiz Henrique Gonçalves Platini
-- SGBD: PostgreSQL
-- Conteúdo: 1 tabela (vendas) + 10.000 registros
-- ---------------------------------------------------------------------
-- COMO USAR:
--   1) Conecte-se ao banco pela extensão PostgreSQL do VS Code
--   2) Abra este arquivo e execute-o por completo
--   3) Confira com: SELECT COUNT(*) FROM vendas;  -> deve retornar 10000
-- =====================================================================

DROP TABLE IF EXISTS vendas;

CREATE TABLE vendas (
    id_venda            INTEGER      PRIMARY KEY,
    data_venda          DATE         NOT NULL,
    nome_cliente        VARCHAR(80)  NOT NULL,
    cidade              VARCHAR(40)  NOT NULL,
    estado              CHAR(2)      NOT NULL,
    categoria           VARCHAR(30)  NOT NULL,
    produto             VARCHAR(60)  NOT NULL,
    quantidade          INTEGER      NOT NULL,
    preco_unitario      NUMERIC(10,2) NOT NULL,
    desconto_percentual NUMERIC(5,2) NOT NULL,
    forma_pagamento     VARCHAR(20)  NOT NULL,
    vendedor            VARCHAR(40)  NOT NULL,
    status_entrega      VARCHAR(15)  NOT NULL
);

